class Dart {
  void calculateProbability() {
    List<int> dartsToThrow = [5, 6];
    int maxDistance = 1;
    for (int numDarts in dartsToThrow) {
      double winCondition1 = calculateWinCondition(numDarts, maxDistance);
      if (!winCondition1) break;

      maxDistance++;
    }

    double totalOutcomes = pow(30 + 2 * maxDistance, numDarts);
    double winningOutcomes = calculateWinningOutcomes(numDarts, maxDistance);
    double probability = winningOutcomes / totalOutcomes;
    print(probability.toStringAsFixed(4));
  }

  bool calculateWinCondition(int numDarts, int distance) {
    return (numDarts >= 3 && distance <= 8) || 
           (numDarts == 2 && distance > 7) || 
           (numDarts == 1 && distance <= 9);
  }

  double calculateWinningOutcomes(int numDarts, int distance) {
    switch (numDarts) {
      case 1:
        return pow(distance, 2);

      case 2:
        return ((distance - 1) * distance) + 
               (pow(distance, 2)) + 
               (double.parse((numDarts.toDouble() * 5).toString()) - 1) * 
                   (distance * (distance - 1)) / 2;

      default:
        return ((distance - 1) * distance) + 
               (pow(distance, 2)) + 
               (double.parse((numDarts.toDouble() * 5).toString()) - 1) * 
                   (distance * (distance - 1)) / 2;
    }
  }
}

