    if (n == 1 || n <= 0) return;

    final List<int> processes = [2 * n];
    while (true) {
      int minProcessId = -1, minTurnoverTime = 999999;

      for (int process in processes) {
        if (process < minTurnoverTime) {
          minProcessId = process;
          minTurnoverTime = process;
        }
      }

      print('turning over to: $minProcessId');
      await Future.delayed(Duration(seconds: minTurnoverTime));
      if (minProcessId != null && minProcessId % 2 == 0) {
