class Solution {
  String NG(List<String> words, int k) {
    // Sort the list of words based on their lengths in descending order
    List<int> lengths = words.map((word) => word.length).toList();

    // Extract the indices corresponding to the top-k longest words
    List<int> maxLengthIndices = getTopKLongestIndices(lengths, k);

    // Get the actual words at these indices and sort them alphabetically
    List<String> selectedWords = [];
    for (int index : maxLengthIndices) {
      selectedWords.add(words[index]);
    }

    // Sort the selected words alphabetically
    selectedWords.sort();

    return selectedWords.join(' ');
  }

  List<int> getTopKLongestIndices(List<int> lengths, int k) {
    List<MapEntry<int, int>> lengthIndexPairs = [];
    for (int i = 0; i < lengths.length; i++) {
      lengthIndexPairs.add(MapEntry(lengths[i], i));
    }

    // Sort pairs by length in descending order
    lengthIndexPairs.sort((a, b) => b.key.compareTo(a.key));

    // Extract only the top-k indices from sorted pairs
    List<int> result = [];
    for (int i = 0; i < k && i < lengthIndexPairs.length; i++) {
      result.add(lengthIndexPairs[i].value);
    }

    return result;
  }
}

