class RBTree {
  Node root, sentinel;

  RBTree() : sentinel = Node(-1), root = null {}

  void insertNode(Node newNode) {
    if (root == null || root.right != null) return;
    root.left = newNode;
    root.right = sentinel;
    root = newNode;
  }

  void printToConsole() {
    print(root?.value ?? -1);
  }
}

