List<bool?> bronKerbosch(List<List<int>> graph, [int u = -1]) {
  if (u < 0) {
    u = 0;
  } else {
    u += 1; // adjust index since we're using a list-based representation.
  }

  bool? status = null;
  while (!graph[u].isEmpty && !status) {
    var v = graph[u][0]; // pick first neighbor of current vertex

    if (v != null) {
      status = true; // mark as visited

      // Remove all neighbors connected to this vertex from other vertices' lists.
      for (var w = 0; w < graph.length; w++) {
        if (w != u && graph[w].contains(v)) {
          graph[w].removeAt(0); // remove the matched pair
        }
      }

      // Recurse on next unvisited vertex that is not yet marked or has no more connections left.
      var t = u + 1;
      while (t < graph.length && (graph[t].isEmpty || status)) {
        t++;
      }

      if (t >= graph.length) break; // reached end of path

      return bronKerbosch(graph, t);
    }

    // No valid move found at this level; backtrack by removing last connection made.
    graph[u] = []; // clear current vertex's remaining edges
    return false;
  }

  return status ?? true; // either success (true), failure (false), or neutral case where result doesn't matter
}

