      if (i[0] == -1 || i[1] == -1) continue;

      switch (i[1]) {
        case 'R':
          output.add(MapEntry(i[0], '*'));
          break;
        case 'L':
          output.add(MapEntry(-i[0], '/'));
          break;
        default:
