    s += 1;
  }

  if (s == 1) {
    int result = powerModulus(n, (p + 1) ~/ 4, p);
    return Solution(result, p - result, true);
  }

  // Find a non-square z such that (z | p) = -1
  int z = 2;
  while (legendre(z, p) != p - 1) {
    z += 1;
  }

  int c = powerModulus(z, q, p);
  int t = powerModulus(n, q, p);
