class ShuntingYard {
  static String toPostfix(String expression) {
    final output = []; // Postfix notation (as a list of strings for easy manipulation)
    final stack = <String>[]; // Stack for operators and parentheses

    const precedence = {'(':0, '+':1, '-':1, '*':2, '/':2};
    final associativity = {'+':'L', '-':'L', '*':'L', '/':'L'}; 

    int operatorPrecedence(String op) => precedence[op];

    void applyAssociativity(int leftPrec, int rightPrec, bool isLeftAssoc) => isLeftAssoc ? leftPrec >= rightPrec : leftPrec > rightPrec;

    for (var token in expression.split('')){
      if (token == '('){
        stack.add(token);
      } else if (token == ')'){
        while(stack.last != '('){
          output.add(stack.removeLast());
        }
        stack.removeLast(); // Remove the opening parenthesis
      } else if (_isOperator(token)){
        while(stack.isNotEmpty && _isOperator(stack.last) && applyAssociativity(operatorPrecedence(token),operatorPrecedence(stack.last),associativity[token])){
          output.add(stack.removeLast());
        }
        stack.add(token);
      } else {
        output.add(token);
      }
    }

    while(stack.isNotEmpty){
      output.add(stack.removeLast());
    }

    return output.join("");
  }

  static bool _isOperator(String s) => ['+', '-', '*', '/', '(', ')'].contains(s);
}

